function _extends() {
  _extends = Object.assign || function (target) {
    for (var i = 1; i < arguments.length; i++) {
      var source = arguments[i];

      for (var key in source) {
        if (Object.prototype.hasOwnProperty.call(source, key)) {
          target[key] = source[key];
        }
      }
    }

    return target;
  };

  return _extends.apply(this, arguments);
}

var escapes = [[/\s-/g, ' \\-']];

function escape(string) {
  return escapes.reduce(function (accumulator, escape) {
    return accumulator.replace(escape[0], escape[1]);
  }, string);
}

function extraFootLink(child) {
  var footLink = null;

  if (child && child.childNodes && child.childNodes[1] && child.childNodes[1].childNodes) {
    try {
      var ref = child.childNodes[0].innerHTML;
      var desc = child.childNodes[1].childNodes[0].nodeValue;
      var link = child.childNodes[1].childNodes[1].innerHTML;

      if (ref && desc && link && link.match(/https?:\/\//)) {
        footLink = {
          ref: ref,
          desc: desc,
          link: link
        };
      }
    } catch (e) {}
  }

  return footLink;
}

function extraFootLinks(node) {
  var sections = node.querySelectorAll('section');
  var footLinks = [];
  Array.from(sections).forEach(function (section) {
    Array.from(section.childNodes).forEach(function (child) {
      var footLink = extraFootLink(child);

      if (footLink) {
        footLinks.push(_extends({}, footLink, {
          desc: footLink.desc.replace(': ', '')
        }));
      }
    });
  });
  return footLinks;
}

var applyWechatRule = function applyWechatRule(service) {
  // 公式
  var oldBlankReplace = service.rules.blankRule.replacement;
  service.rules.blankRule = {
    replacement: function replacement(content, node, options) {
      if (node.nodeName === 'svg') {
        node.parentNode.unNeedEscape = true;
        return node.outerHTML;
      }

      return oldBlankReplace.call(service.rules, content, node, options);
    }
  };
  service.addRule('paragraph', {
    filter: 'p',
    replacement: function replacement(content, node) {
      return '\n\n' + node.unNeedEscape ? content : escape(content) + '\n\n';
    }
  });
  service.addRule('wechatImg', {
    filter: 'img',
    replacement: function replacement(_content, node) {
      var alt = node.getAttribute('alt') || '';

      if (node.nextElementSibling && node.nextElementSibling.nodeName === 'FIGCAPTION') {
        alt = node.nextElementSibling.textContent || '';
      }

      var src = node.getAttribute('data-src') || node.getAttribute('src') || '';
      var title = node.title || '';
      var titlePart = title ? ' "' + title + '"' : '';
      return src ? '![' + alt + ']' + '(' + src + titlePart + ')' : '';
    }
  }); // @ts-ignore

  service.remove(['figcaption', 'sup']);
  service.addRule('wechatFootnoteLink-section', {
    filter: function filter(node) {
      var rst = false;

      if (node.nodeName === 'SECTION') {
        Array.from(node.childNodes).forEach(function (child) {
          if (extraFootLink(child)) {
            rst = true;
          }
        });
      } // if (node.nodeName === 'H3' && node.innerHTML === '参考资料') {
      //   rst = true;
      // }


      return rst;
    },
    replacement: function replacement() {
      return '';
    }
  });
  service.addRule('wechatFootnoteLink', {
    filter: function filter(node) {
      var isWechatLink = node.nodeName === 'SPAN' && node.nextElementSibling && node.nextElementSibling.nodeName === 'SUP';
      return !!isWechatLink;
    },
    replacement: function replacement(content, node, options) {
      if (options.env && options.env.footLinks) {
        var footLinks = options.env.footLinks;
        var ref = node.nextElementSibling ? node.nextElementSibling.innerHTML : '1';
        var footLink = footLinks.find(function (item) {
          return item.ref === ref;
        }) || {};
        var desc = footLink.desc;
        var link = footLink.link;
        return "[" + content + "](" + link + " \"" + desc + "\")";
      }

      return content;
    }
  });
  service.addRule('wechatFormula', {
    filter: function filter(node) {
      var isFormula = node.getAttribute('data-formula');
      return !!isFormula;
    },
    replacement: function replacement(_content, node) {
      var formula = node.getAttribute('data-formula');

      if (formula) {
        var formulaType = node.getAttribute('data-formula-type');
        var isBlockFormula = formulaType === 'block-equation';
        return isBlockFormula ? "\n\n$$\n" + formula.trimEnd() + "\n$$\n\n" : "$" + formula.trimEnd() + "$";
      }

      return '';
    }
  });
  service.keep(function (node) {
    return node.nodeName === 'SPAN' && node.style.display === 'block' && node.style.textAlign === 'center';
  });
};

export { applyWechatRule, extraFootLinks };